#!/usr/bin/env node
const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/refs.jsonl';

const D3 = 'http://json-schema.org/draft-03/schema#';
const D4 = 'http://json-schema.org/draft-04/schema#';
const D6 = 'http://json-schema.org/draft-06/schema#';
const D7 = 'http://json-schema.org/draft-07/schema#';
const D19 = 'https://json-schema.org/draft/2019-09/schema';
const D20 = 'https://json-schema.org/draft/2020-12/schema';
const ALL = [D3, D4, D6, D7, D19, D20];
const MODERN = [D7, D19, D20];

const pairs = []; // [instanceObj, schemaObj]
function add(a, b) { pairs.push([a, b]); }
// add same schema under every draft in list (schema given WITHOUT $schema)
function sweep(a, b, drafts = ALL) {
  for (const s of drafts) add(a, Object.assign({ $schema: s }, b));
}

// ---------- 1. basic pointer refs ----------
add('x', { $ref: '#/definitions/a', definitions: { a: { type: 'integer' } } });
add('x', { $ref: '#/$defs/a', $defs: { a: { type: 'integer' } } });
add(5, { $ref: '#/$defs/a', $defs: { a: { type: 'integer' } } });
sweep('x', { $ref: '#/definitions/a', definitions: { a: { type: 'integer' } } });
sweep('x', { $ref: '#/$defs/a', $defs: { a: { type: 'integer' } } });
sweep(5, { $ref: '#/definitions/a', definitions: { a: { type: 'integer' } } });

// ---------- 2. $ref sibling keywords ----------
sweep('x', { $ref: '#/definitions/a', minLength: 10, definitions: { a: { type: 'string' } } });
sweep('x', { $ref: '#/$defs/a', minLength: 10, pattern: '^z', $defs: { a: { type: 'integer' } } });
sweep('x', { $ref: '#/$defs/a', minLength: 10, pattern: '^z', maxLength: 0, $defs: { a: { type: 'integer' } } });
sweep('x', { $ref: '#/$defs/a', type: 'integer', $defs: { a: { type: 'string' } } });
// sibling on a nested (non-root) ref
sweep({ p: 'x' }, { properties: { p: { $ref: '#/$defs/a', minLength: 10 } }, $defs: { a: { type: 'string' } } });

// ---------- 3. error counting through refs ----------
sweep('x', { $ref: '#/$defs/a', $defs: { a: { minLength: 10, pattern: '^z' } } });
sweep('x', { $ref: '#/$defs/a', $defs: { a: { $ref: '#/$defs/b' }, b: { minLength: 10, pattern: '^z' } } });
sweep({ p: 'x', q: 'y' }, { definitions: { a: { type: 'integer' } }, properties: { p: { $ref: '#/definitions/a' }, q: { $ref: '#/definitions/a' } } });
sweep('x', { definitions: { a: { minLength: 10, pattern: '^z', maxLength: 0 } }, allOf: [{ $ref: '#/definitions/a' }] });
sweep('x', { definitions: { a: { minLength: 10, pattern: '^z' } }, anyOf: [{ $ref: '#/definitions/a' }] });
sweep('x', { definitions: { a: { minLength: 10, pattern: '^z' } }, oneOf: [{ $ref: '#/definitions/a' }] });
sweep('x', { definitions: { a: { minLength: 10 } }, not: { $ref: '#/definitions/a' } });
sweep(['x', 'y'], { definitions: { a: { type: 'integer' } }, items: { $ref: '#/definitions/a' } }, [D6, D7, D19, D20]);

// ---------- 4. root recursion via # ----------
add({ a: { a: 1 } }, { type: 'object', properties: { a: { $ref: '#' } } });
add({ a: { a: 'x' } }, { type: 'object', properties: { a: { $ref: '#' } } });
sweep({ a: { a: { a: 1 } } }, { type: 'object', properties: { a: { $ref: '#' } } });
sweep('x', { $ref: '#' });
sweep('x', { $ref: '' });
sweep({ p: 1 }, { $ref: '#/properties/p', properties: { p: { type: 'string' } } });

// ---------- 5. pointer escaping ----------
add('x', { $defs: { 'a/b': { type: 'integer' } }, $ref: '#/$defs/a~1b' });
add('x', { $defs: { 'a~b': { type: 'integer' } }, $ref: '#/$defs/a~0b' });
add('x', { $defs: { 'a b': { type: 'integer' } }, $ref: '#/$defs/a b' });
add('x', { $defs: { 'a b': { type: 'integer' } }, $ref: '#/$defs/a%20b' });
add('x', { $defs: { 'a%b': { type: 'integer' } }, $ref: '#/$defs/a%25b' });
add('x', { $defs: { 'a%b': { type: 'integer' } }, $ref: '#/$defs/a%b' });
add('x', { $defs: { 'a%25b': { type: 'integer' } }, $ref: '#/$defs/a%2525b' });
add('x', { $defs: { 'tilde~1': { type: 'integer' } }, $ref: '#/$defs/tilde~01' });
add('x', { $defs: { 'a"b': { type: 'integer' } }, $ref: '#/$defs/a"b' });
add('x', { $defs: { '': { type: 'integer' } }, $ref: '#/$defs/' });
add('x', { $defs: { 'a+b': { type: 'integer' } }, $ref: '#/$defs/a+b' });
add('x', { $defs: { 'a#b': { type: 'integer' } }, $ref: '#/$defs/a%23b' });
sweep('x', { definitions: { 'a/b': { type: 'integer' } }, $ref: '#/definitions/a~1b' });
sweep('x', { definitions: { 'a b': { type: 'integer' } }, $ref: '#/definitions/a%20b' });

// ---------- 6. array-index pointers ----------
add('x', { prefixItems: [{ type: 'integer' }], $ref: '#/prefixItems/0' });
add('x', { items: [{ type: 'integer' }], $ref: '#/items/0' });
sweep('x', { items: [{ type: 'integer' }, { type: 'boolean' }], $ref: '#/items/1' });
sweep('x', { anyOf: [{ type: 'integer' }], $ref: '#/anyOf/0' });
sweep('x', { $defs: { a: [{ type: 'integer' }] }, $ref: '#/$defs/a/0' });
add('x', { $defs: { a: [{ type: 'integer' }] }, $ref: '#/$defs/a/5' });
add('x', { $defs: { a: [{ type: 'integer' }] }, $ref: '#/$defs/a/x' });
add('x', { enum: [1, 2], $ref: '#/enum/0' });

// ---------- 7. nonexistent pointers / unresolvable ----------
sweep('x', { $ref: '#/nope' });
sweep('x', { $ref: '#/$defs/a' });
add('x', { $ref: '#/definitions' });
add('x', { definitions: { a: { type: 'integer' } }, $ref: '#/definitions' });
add('x', { definitions: { a: { type: 'integer' } }, $ref: '#/definitions/b' });
add('x', { $ref: 'nope' });
add('x', { $ref: 'other.json' });
sweep('x', { $ref: 'http://example.com/x' });
add('x', { $ref: 'https://example.com/x#/foo' });
add('x', { $ref: 'urn:uuid:deadbeef' });
add('x', { $ref: 'file:///etc/passwd' });
add('x', { $ref: '#foo' });
sweep('x', { $ref: '#foo' });

// ---------- 8. malformed $ref values ----------
sweep('x', { $ref: 5 });
add('x', { $ref: null });
add('x', { $ref: true });
add('x', { $ref: [] });
add('x', { $ref: {} });

// ---------- 9. ref target not an object schema ----------
sweep('x', { definitions: { a: false }, $ref: '#/definitions/a' });
sweep('x', { definitions: { a: true }, $ref: '#/definitions/a' });
sweep('x', { definitions: { a: 'nonschema' }, $ref: '#/definitions/a' });
add('x', { definitions: { a: 5 }, $ref: '#/definitions/a' });
add('x', { definitions: { a: null }, $ref: '#/definitions/a' });

// ---------- 10. $id / id base URI ----------
sweep('x', { $id: 'http://x/', $defs: { a: { $id: 'b', type: 'integer' } }, $ref: 'b' });
sweep('x', { $id: 'http://x/', $defs: { a: { $id: 'b', type: 'integer' } }, $ref: 'http://x/b' });
sweep('x', { id: 'http://x/', definitions: { a: { id: 'b', type: 'integer' } }, $ref: 'b' });
sweep('x', { id: 'http://x/', definitions: { a: { id: 'b', type: 'integer' } }, $ref: 'http://x/b' });
sweep('x', { $id: 'http://x/', definitions: { a: { $id: 'b', type: 'integer' } }, $ref: 'b' });
sweep('x', { $id: 'http://x/', definitions: { a: { $id: 'b', type: 'integer' } }, $ref: 'http://x/b' });
sweep('x', { id: 'http://x/', definitions: { a: { id: 'http://x/b', type: 'integer' } }, $ref: 'http://x/b' });
sweep('x', { $defs: { a: { $id: 'http://y/b', type: 'integer' } }, $ref: 'http://y/b' });
sweep('x', { definitions: { a: { $id: 'http://y/b', type: 'integer' } }, $ref: 'http://y/b' });
// non-root $ref => root $id IS honored for draft6/7 too
sweep({ p: 'x' }, { $id: 'http://x/', definitions: { a: { $id: 'b', type: 'integer' } }, properties: { p: { $ref: 'http://x/b' } } });
sweep({ p: 'x' }, { $id: 'http://x/', definitions: { a: { $id: 'b', type: 'integer' } }, properties: { p: { $ref: 'b' } } });
sweep({ p: 'x' }, { id: 'http://x/', definitions: { a: { id: 'b', type: 'integer' } }, properties: { p: { $ref: 'http://x/b' } } });
sweep({ p: 'x' }, { $id: 'http://x/', $defs: { a: { $id: 'b', type: 'integer' } }, properties: { p: { $ref: 'http://x/b' } } });
// relative path resolution
add('x', { $id: 'http://x/a/c.json', $defs: { d: { $id: 'e.json', type: 'integer' } }, allOf: [{ $ref: 'e.json' }] });
add('x', { $id: 'http://x/a/c.json', $defs: { d: { $id: 'e.json', type: 'integer' } }, allOf: [{ $ref: 'http://x/a/e.json' }] });
add('x', { $id: 'http://x/a/c.json', $defs: { d: { $id: '/e.json', type: 'integer' } }, allOf: [{ $ref: 'http://x/e.json' }] });
add('x', { $id: 'http://x/a/c.json', $defs: { d: { $id: 'e.json', type: 'integer' } }, allOf: [{ $ref: 'http://x/e.json' }] });
add('x', { $id: 'http://x/', $defs: { d: { $id: 'b', $defs: { z: { type: 'integer' } } } }, allOf: [{ $ref: 'http://x/b#/$defs/z' }] });
add('x', { $id: 'http://x/', $defs: { d: { $id: 'b', $defs: { z: { type: 'integer' } } } }, allOf: [{ $ref: '#/$defs/d/$defs/z' }] });
// $id inside properties (applicator) subresource
sweep({ p: 'x' }, { properties: { p: { $id: 'http://y/b', type: 'integer' } }, allOf: [{ $ref: 'http://y/b' }] });
// $id on root only, self ref by absolute uri
sweep('x', { $id: 'http://x/root', allOf: [{ $ref: 'http://x/root#/$defs/a' }], $defs: { a: { type: 'integer' } } });
sweep('x', { $id: 'http://x/root', allOf: [{ $ref: 'http://x/root' }], type: 'integer' });

// ---------- 11. anchors ----------
sweep({ p: 'x' }, { $defs: { a: { $anchor: 'foo', type: 'integer' } }, properties: { p: { $ref: '#foo' } } });
sweep({ p: 'x' }, { definitions: { a: { $anchor: 'foo', type: 'integer' } }, properties: { p: { $ref: '#foo' } } });
sweep({ p: 'x' }, { definitions: { a: { $id: '#foo', type: 'integer' } }, properties: { p: { $ref: '#foo' } } });
sweep({ p: 'x' }, { definitions: { a: { id: '#foo', type: 'integer' } }, properties: { p: { $ref: '#foo' } } });
sweep({ p: 'x' }, { $defs: { a: { $id: '#foo', type: 'integer' } }, properties: { p: { $ref: '#foo' } } });
add({ p: 'x' }, { $id: 'http://x/', $defs: { a: { $anchor: 'foo', type: 'integer' } }, properties: { p: { $ref: 'http://x/#foo' } } });
add({ p: 'x' }, { $defs: { a: { $id: 'http://y/b', $anchor: 'foo', type: 'integer' } }, properties: { p: { $ref: 'http://y/b#foo' } } });

// ---------- 12. $recursiveRef / $recursiveAnchor ----------
sweep({ p: { p: 1 } }, { $recursiveAnchor: true, type: 'object', properties: { p: { $recursiveRef: '#' } } }, MODERN);
sweep({ p: 1 }, { $recursiveAnchor: true, type: 'object', properties: { p: { $recursiveRef: '#' } } }, MODERN);
sweep({}, { $recursiveAnchor: true, type: 'object', properties: { p: { $recursiveRef: '#' } } }, MODERN);
sweep('x', { $recursiveRef: '#' }, MODERN);
sweep('x', { $recursiveRef: '#foo' }, MODERN);
add({ p: 1 }, { $schema: D19, $recursiveAnchor: false, type: 'object', properties: { p: { $recursiveRef: '#' } } });

// ---------- 13. $dynamicRef / $dynamicAnchor ----------
sweep({ p: { p: 1 } }, { $dynamicAnchor: 'n', type: 'object', properties: { p: { $dynamicRef: '#n' } } }, MODERN);
sweep({ p: 1 }, { $dynamicAnchor: 'n', type: 'object', properties: { p: { $dynamicRef: '#n' } } }, MODERN);
sweep('x', { $dynamicRef: '#nope' }, MODERN);
add('x', { $schema: D20, $defs: { a: { $dynamicAnchor: 'n', type: 'integer' } }, $dynamicRef: '#n' });
add('x', { $schema: D20, $defs: { a: { $anchor: 'n', type: 'integer' } }, $dynamicRef: '#n' });
add('x', { $schema: D20, $defs: { a: { $dynamicAnchor: 'n', type: 'integer' } }, $ref: '#n' });
add('x', { $schema: D19, $defs: { a: { $dynamicAnchor: 'n', type: 'integer' } }, $dynamicRef: '#n' });

// ---------- 14. meta-schema refs (offline?) ----------
for (const u of [D3, D4, D6, D7, D19, D20,
  'https://json-schema.org/draft/2020-12/meta/core',
  'https://json-schema.org/draft/2020-12/meta/validation',
  'https://json-schema.org/draft/2019-09/meta/validation',
  'http://json-schema.org/schema#',
  'http://json-schema.org/draft-07/schema']) {
  add('x', { $ref: u });
}
add({ type: 'string' }, { $ref: D7 });
add({ type: 'bogus' }, { $ref: D7 });
add({ type: 'bogus', minLength: 'x' }, { $ref: D7 });
add(-5, { $ref: 'https://json-schema.org/draft/2020-12/meta/validation#/$defs/nonNegativeInteger' });
add(-5, { $ref: 'http://json-schema.org/draft-07/schema#/definitions/nonNegativeInteger' });
add(5, { $ref: 'http://json-schema.org/draft-07/schema#/definitions/nonNegativeInteger' });
add('x', { $ref: 'http://json-schema.org/draft-07/schema#/properties/type' });
add('x', { $ref: 'https://json-schema.org/draft/2020-12/schema#/$defs/nonNegativeInteger' });
add({ type: 'string' }, { $schema: D7, $ref: D7 });
add({}, { $ref: D20 });

// ---------- 15. misc interactions ----------
add('x', { $schema: D7, $ref: '#/definitions/a', $id: 'http://ignored/', definitions: { a: { type: 'integer' } } });
sweep('x', { $ref: '#/$defs/a', $defs: { a: { $ref: '#/$defs/b' }, b: { $ref: '#/$defs/c' }, c: { type: 'integer' } } });
sweep('x', { $defs: { a: { $ref: '#/$defs/b' }, b: { $ref: '#/$defs/a' } }, allOf: [{ $ref: '#/$defs/a' }] });
