cd /workspace/probes && cat > /tmp/err.js <<'EOF'
const {execFileSync}=require("child_process");const fs=require("fs");
const L=fs.readFileSync("/workspace/probes/refs.jsonl","utf8").trim().split("\n").map(JSON.parse);
const map=new Map();
for(const x of L){ if(x.exit===0) continue;
  let err="";
  try{execFileSync("/workspace/dataset/test13_executable",["--a",x.a,"--b",x.b],{stdio:["ignore","pipe","pipe"]});}
  catch(e){const s=(e.stderr||"").toString().trim().split("\n");
    const cand=s.filter(l=>/^[A-Za-z_][\w.]*(Error|Exception):/.test(l));
    err=cand.length?cand[cand.length-1]:s[s.length-1];}
  const cls=err.split(":")[0]+(err.includes("PointerToNowhere")?" / PointerToNowhere":err.includes("Unresolvable")?" / Unresolvable":err.includes("NoSuchAnchor")?" / NoSuchAnchor":"");
  if(!map.has(cls))map.set(cls,[]);map.get(cls).push(x.b);
}
for(const [k,v] of map){console.log("###",k,"  count="+v.length);for(const b of v.slice(0,4))console.log("   ",b.slice(0,140));}
EOF
node /tmp/err.js

